insert into audio_clips (id, text, voice, channel) values ('0bf957ed219656f3', 'Bホールを押さえました。広さも予算内に収まります。', 'manager_m', 'in_person') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
